<?php

namespace Database\Seeders;

/** Seeds `programs` from database/seeders/data/programs.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class ProgramsSeeder extends ContentSeederBase
{
    public const TABLE = 'programs';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        // programs.name (legacy column returned by the API) mirrors name_ar.
        $images = ['image' => 'programs'];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('programs') as $row) {
            $row['name'] ??= $row['name_ar'] ?? null;
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
